    # Determine search complexity
    filter_count = sum([
        query is not None,
        file_type is not None,
        min_size is not None,
        max_size is not None
    ])

    # For complex queries with multiple filters, enable optimization
    is_complex_query = filter_count >= SEARCH_CONFIG.get("min_filters_for_optimization", 2)

    # Attempt to use optimized search context for complex queries
    expanded_user = None
    original_user = None
    if is_complex_query:
